-- i18n: en/es translations of every "portugues" question
-- (138 questions x 2 locales = 276 rows). Only writes
-- question_translations; questions (the pt-BR original, including
-- correct_index) is never touched.
--
-- options keep exactly the original order: correct_index is positional and
-- is always read from the original row. The join below also refuses any row
-- whose option count differs from the original, so a bad line can never
-- turn into a question with the wrong answer marked.
--
-- Keyed by the real questions.id read from the live database. Idempotent
-- (on conflict do update). Check afterwards with i18n_questions_checkup.sql.

insert into question_translations (question_id, locale, prompt, options, explanation)
select v.id::uuid, v.locale, v.prompt, v.options, v.explanation
from (values
  ('53968ccb-e166-49f5-ad3b-849032ff0a38', 'en',
   'Choose the option in which noun agreement is correct in Portuguese:',
   array['Ela mesma resolveu o problema.', 'Ela mesmo resolveu o problema.', 'Elas mesmo resolveram o problema.', 'Ele mesma resolveu o problema.'],
   '"Mesmo(a)" used for emphasis agrees in gender and number with the noun/pronoun it refers to; "ela" requires "mesma".'),
  ('53968ccb-e166-49f5-ad3b-849032ff0a38', 'es',
   'Señala la alternativa en la que la concordancia nominal es correcta en portugués:',
   array['Ela mesma resolveu o problema.', 'Ela mesmo resolveu o problema.', 'Elas mesmo resolveram o problema.', 'Ele mesma resolveu o problema.'],
   '"Mesmo(a)" usado como refuerzo concuerda en género y número con el sustantivo/pronombre al que se refiere; "ela" exige "mesma".'),
  ('3718d4a6-077a-4ab2-ba43-9933bcd5a277', 'en',
   'Choose the option that is correct in Portuguese regarding noun agreement:',
   array['Fizeram um trabalho bem feito.', 'Fizeram um trabalho bem feita.', 'Fizeram uma trabalho bem feito.', 'Fizeram um trabalho bens feito.'],
   'The adjective "feito" must agree in gender and number with the noun "trabalho" (masculine singular).'),
  ('3718d4a6-077a-4ab2-ba43-9933bcd5a277', 'es',
   'Señala la alternativa correcta en portugués en cuanto a la concordancia nominal:',
   array['Fizeram um trabalho bem feito.', 'Fizeram um trabalho bem feita.', 'Fizeram uma trabalho bem feito.', 'Fizeram um trabalho bens feito.'],
   'El adjetivo "feito" debe concordar en género y número con el sustantivo "trabalho" (masculino singular).'),
  ('0be6745e-fedb-4ad7-b39c-0ebc29348acd', 'en',
   'Choose the option in which noun agreement is correct in Portuguese:',
   array['Estão anexas ao processo as certidões solicitadas.', 'Estão anexo ao processo as certidões solicitadas.', 'Está anexas ao processo as certidões solicitadas.', 'Estão anexos ao processo as certidões solicitadas.'],
   'The adjective "anexo" varies in gender and number; since "certidões" is feminine plural, the correct form is "anexas".'),
  ('0be6745e-fedb-4ad7-b39c-0ebc29348acd', 'es',
   'Señala la alternativa en la que la concordancia nominal es correcta en portugués:',
   array['Estão anexas ao processo as certidões solicitadas.', 'Estão anexo ao processo as certidões solicitadas.', 'Está anexas ao processo as certidões solicitadas.', 'Estão anexos ao processo as certidões solicitadas.'],
   'El adjetivo "anexo" varía en género y número; como "certidões" es femenino plural, la forma correcta es "anexas".'),
  ('9aa52ba3-c3e5-4f42-92f3-c22183f0b01a', 'en',
   'Choose the option that is correct in Portuguese regarding noun agreement:',
   array['É proibida a entrada de visitantes.', 'É proibido a entrada de visitantes.', 'É proibidos a entrada de visitantes.', 'É proibida entrada de visitantes.'],
   'Before a noun preceded by a definite article ("a entrada"), the expression "é proibido" must agree in gender and number: "é proibida a entrada".'),
  ('9aa52ba3-c3e5-4f42-92f3-c22183f0b01a', 'es',
   'Señala la alternativa correcta en portugués en cuanto a la concordancia nominal:',
   array['É proibida a entrada de visitantes.', 'É proibido a entrada de visitantes.', 'É proibidos a entrada de visitantes.', 'É proibida entrada de visitantes.'],
   'Ante un sustantivo precedido de artículo definido ("a entrada"), la expresión "é proibido" debe concordar en género y número: "é proibida a entrada".'),
  ('351990dd-0be0-49b9-a158-d27ca2772538', 'en',
   'Choose the option in which noun agreement is correct in Portuguese:',
   array['Segue anexo o comprovante de pagamento.', 'Segue anexa o comprovante de pagamento.', 'Seguem anexo os comprovante de pagamento.', 'Segue anexos o comprovante de pagamento.'],
   '"Anexo" must agree with the noun it refers to; since "comprovante" is masculine singular, the correct form is "anexo".'),
  ('351990dd-0be0-49b9-a158-d27ca2772538', 'es',
   'Señala la alternativa en la que la concordancia nominal es correcta en portugués:',
   array['Segue anexo o comprovante de pagamento.', 'Segue anexa o comprovante de pagamento.', 'Seguem anexo os comprovante de pagamento.', 'Segue anexos o comprovante de pagamento.'],
   '"Anexo" debe concordar con el sustantivo al que se refiere; como "comprovante" es masculino singular, la forma correcta es "anexo".'),
  ('c103f29b-f274-4afd-a8a3-90e0f82bbe5c', 'en',
   'Choose the option in which verb agreement follows standard Portuguese:',
   array['Faz dois anos que ele se mudou.', 'Fazem dois anos que ele se mudou.', 'Haviam muitos problemas naquela empresa.', 'Deve haverem soluções para isso.'],
   'The verbs "fazer" (indicating time) and "haver" (meaning "to exist") are impersonal and must always stay in the 3rd person singular.'),
  ('c103f29b-f274-4afd-a8a3-90e0f82bbe5c', 'es',
   'Señala la alternativa en la que la concordancia verbal sigue la norma estándar del portugués:',
   array['Faz dois anos que ele se mudou.', 'Fazem dois anos que ele se mudou.', 'Haviam muitos problemas naquela empresa.', 'Deve haverem soluções para isso.'],
   'Los verbos "fazer" (indicando tiempo) y "haver" (en el sentido de existir) son impersonales y deben quedar siempre en la 3.ª persona del singular.'),
  ('b2bff02c-ea5f-4bca-8899-63c0a6aa0420', 'en',
   'Choose the option in which verb agreement is correct in Portuguese:',
   array['Nós vamos ao cinema hoje.', 'Nós vai ao cinema hoje.', 'Eu vamos ao cinema hoje.', 'Vós vai ao cinema hoje.'],
   'The verb must agree in person and number with the subject; "nós" requires the form "vamos".'),
  ('b2bff02c-ea5f-4bca-8899-63c0a6aa0420', 'es',
   'Señala la alternativa en la que la concordancia verbal es correcta en portugués:',
   array['Nós vamos ao cinema hoje.', 'Nós vai ao cinema hoje.', 'Eu vamos ao cinema hoje.', 'Vós vai ao cinema hoje.'],
   'El verbo debe concordar en persona y número con el sujeto; "nós" exige la forma "vamos".'),
  ('e0697d13-9b28-4026-85fd-5953cda6cac4', 'en',
   'Choose the option in which verb agreement follows standard Portuguese:',
   array['Mais de um aluno faltou à prova.', 'Mais de um aluno faltaram à prova.', 'Um dos aluno faltou à prova.', 'Mais de um alunos faltou à prova.'],
   'The expression "mais de um" followed by a singular noun generally requires a singular verb.'),
  ('e0697d13-9b28-4026-85fd-5953cda6cac4', 'es',
   'Señala la alternativa en la que la concordancia verbal sigue la norma estándar del portugués:',
   array['Mais de um aluno faltou à prova.', 'Mais de um aluno faltaram à prova.', 'Um dos aluno faltou à prova.', 'Mais de um alunos faltou à prova.'],
   'La expresión "mais de um" seguida de un sustantivo en singular exige, por regla general, el verbo en singular.'),
  ('49b1d3b4-6874-4ef6-9ad9-8621dfbd2c99', 'en',
   'Choose the option that is correct in Portuguese regarding verb agreement:',
   array['Fazia dez anos que não nos víamos.', 'Faziam dez anos que não nos víamos.', 'Fazem dez anos que não nos víamos.', 'Faziam dez anos atrás que não nos víamos.'],
   'The verb "fazer", indicating elapsed time, is impersonal and stays in the 3rd person singular, even in the past ("fazia").'),
  ('49b1d3b4-6874-4ef6-9ad9-8621dfbd2c99', 'es',
   'Señala la alternativa correcta en portugués en cuanto a la concordancia verbal:',
   array['Fazia dez anos que não nos víamos.', 'Faziam dez anos que não nos víamos.', 'Fazem dez anos que não nos víamos.', 'Faziam dez anos atrás que não nos víamos.'],
   'El verbo "fazer", indicando tiempo transcurrido, es impersonal y queda en la 3.ª persona del singular, incluso en pasado ("fazia").'),
  ('25a6dd51-0578-4e0b-b415-8bf308866093', 'en',
   'Choose the option in which verb agreement is correct in Portuguese:',
   array['Precisa-se de funcionários experientes.', 'Precisam-se de funcionários experientes.', 'Preciso-se de funcionários experientes.', 'Precisam-se funcionários experientes.'],
   'With the indirect transitive verb "precisar" followed by "de", "se" marks an indeterminate subject, and the verb stays in the singular.'),
  ('25a6dd51-0578-4e0b-b415-8bf308866093', 'es',
   'Señala la alternativa en la que la concordancia verbal es correcta en portugués:',
   array['Precisa-se de funcionários experientes.', 'Precisam-se de funcionários experientes.', 'Preciso-se de funcionários experientes.', 'Precisam-se funcionários experientes.'],
   'Con el verbo transitivo indirecto "precisar" seguido de "de", el "se" es índice de indeterminación del sujeto, y el verbo queda en singular.'),
  ('150628c0-aea2-4624-a351-f8c12572caa5', 'en',
   'Choose the option in which the crase (à) is optional in Portuguese, before a feminine possessive pronoun:',
   array['Entreguei o documento à minha secretária.', 'Entreguei o documento à a minha secretária.', 'Entreguei o documento à minhas secretária.', 'Entreguei o documento à minha às secretária.'],
   'Before feminine possessive pronouns, the crase is optional: both "à minha secretária" and "a minha secretária" are accepted by the standard language.'),
  ('150628c0-aea2-4624-a351-f8c12572caa5', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es opcional en portugués, ante un pronombre posesivo femenino:',
   array['Entreguei o documento à minha secretária.', 'Entreguei o documento à a minha secretária.', 'Entreguei o documento à minhas secretária.', 'Entreguei o documento à minha às secretária.'],
   'Ante pronombres posesivos femeninos, la crasis es opcional: tanto "à minha secretária" como "a minha secretária" son aceptadas por la norma estándar.'),
  ('140b7a14-8640-4216-a424-e38472453c84', 'en',
   'Choose the option in which the crase (à) is optional in Portuguese, before a feminine proper name:',
   array['Contei o segredo à Ana.', 'Contei o segredo à à Ana.', 'Contei o segredo às Ana.', 'Contei o segredo à a Ana.'],
   'Before feminine proper names, the crase is optional: both "a Ana" and "à Ana" are accepted.'),
  ('140b7a14-8640-4216-a424-e38472453c84', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es opcional en portugués, ante un nombre propio femenino:',
   array['Contei o segredo à Ana.', 'Contei o segredo à à Ana.', 'Contei o segredo às Ana.', 'Contei o segredo à a Ana.'],
   'Ante nombres propios femeninos, el uso de la crasis es opcional: tanto "a Ana" como "à Ana" son aceptadas.'),
  ('3f404b42-4c7a-4783-a9f0-4c42406919cd', 'en',
   'Choose the option in which the crase (à) is optional in Portuguese, in the expression with "até":',
   array['Foi até à padaria comprar pão.', 'Foi até à à padaria comprar pão.', 'Foi até às padaria comprar pão.', 'Foi até à a padaria comprar pão.'],
   'With the preposition "até" before a feminine word, the crase is optional: "até a padaria" or "até à padaria".'),
  ('3f404b42-4c7a-4783-a9f0-4c42406919cd', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es opcional en portugués, en la expresión con "até":',
   array['Foi até à padaria comprar pão.', 'Foi até à à padaria comprar pão.', 'Foi até às padaria comprar pão.', 'Foi até à a padaria comprar pão.'],
   'Con la preposición "até" ante una palabra femenina, la crasis es opcional: "até a padaria" o "até à padaria".'),
  ('deedfc45-5bee-40f5-9e11-9946629bff47', 'en',
   'Choose the option in which the crase (à) is optional in Portuguese, before a possessive pronoun:',
   array['Dedico esta vitória à minha mãe.', 'Dedico esta vitória à à minha mãe.', 'Dedico esta vitória às minha mãe.', 'Dedico esta vitória à a minha mãe.'],
   'As with other feminine possessives, the crase before "minha mãe" is optional.'),
  ('deedfc45-5bee-40f5-9e11-9946629bff47', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es opcional en portugués, ante un pronombre posesivo:',
   array['Dedico esta vitória à minha mãe.', 'Dedico esta vitória à à minha mãe.', 'Dedico esta vitória às minha mãe.', 'Dedico esta vitória à a minha mãe.'],
   'Al igual que ante otros posesivos femeninos, el uso de la crasis antes de "minha mãe" es opcional.'),
  ('0d34d8b7-4380-4af3-b3f9-85d98bdfd18a', 'en',
   'Choose the option in which the crase (à) is optional in Portuguese:',
   array['Caminhamos até à praça central.', 'Caminhamos até à à praça central.', 'Caminhamos até às praça central.', 'Caminhamos até à a praça central.'],
   'With "até" followed by a feminine word, the crase is optional: "até a praça" or "até à praça".'),
  ('0d34d8b7-4380-4af3-b3f9-85d98bdfd18a', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es opcional en portugués:',
   array['Caminhamos até à praça central.', 'Caminhamos até à à praça central.', 'Caminhamos até às praça central.', 'Caminhamos até à a praça central.'],
   'Con "até" seguido de una palabra femenina, el uso de la crasis es opcional: "até a praça" o "até à praça".'),
  ('b46f3c11-34a9-4827-aae7-292c527ef27e', 'en',
   'Choose the option in which the crase (à) is used correctly in Portuguese to indicate a specific time:',
   array['O show começará às 21 horas.', 'O show começará a 21 horas.', 'O show começará à 21 horas.', 'O show começará as 21 horas.'],
   'Before a specific time, in the plural, the crase is used: "às 21 horas".'),
  ('b46f3c11-34a9-4827-aae7-292c527ef27e', 'es',
   'Señala la alternativa en la que la crasis (à) se usó correctamente en portugués, al indicar una hora determinada:',
   array['O show começará às 21 horas.', 'O show começará a 21 horas.', 'O show começará à 21 horas.', 'O show começará as 21 horas.'],
   'Ante la indicación de horas determinadas, en plural, se usa la crasis: "às 21 horas".'),
  ('58d2be0c-15ab-4b4c-90ca-f58ef34cc946', 'en',
   'Choose the option in which the crase (à) is mandatory in Portuguese, because it is a feminine adverbial phrase:',
   array['O bordado foi feito à mão.', 'O bordado foi feito a mão.', 'O bordado foi feito a à mão.', 'O bordado foi feito na à mão.'],
   'In feminine adverbial phrases formed by "a" + a feminine noun (à mão, à noite, à tarde), the crase is mandatory.'),
  ('58d2be0c-15ab-4b4c-90ca-f58ef34cc946', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es obligatorio en portugués, por tratarse de una locución adverbial femenina:',
   array['O bordado foi feito à mão.', 'O bordado foi feito a mão.', 'O bordado foi feito a à mão.', 'O bordado foi feito na à mão.'],
   'En las locuciones adverbiales femeninas formadas por "a" + sustantivo femenino (à mão, à noite, à tarde), el uso de la crasis es obligatorio.'),
  ('90c0f428-9b34-4359-82af-0a52a569fdbe', 'en',
   'Choose the option in which the crase (à) is used correctly in Portuguese before the relative pronoun "a qual":',
   array['Esta é a empresa à qual me refiro.', 'Esta é a empresa a qual me refiro.', 'Esta é a empresa à a qual me refiro.', 'Esta é a empresa a a qual me refiro.'],
   'Before the relative pronoun "a qual" (feminine), when the verb of the clause requires the preposition "a", the crase is mandatory.'),
  ('90c0f428-9b34-4359-82af-0a52a569fdbe', 'es',
   'Señala la alternativa en la que la crasis (à) se usó correctamente en portugués antes del pronombre relativo "a qual":',
   array['Esta é a empresa à qual me refiro.', 'Esta é a empresa a qual me refiro.', 'Esta é a empresa à a qual me refiro.', 'Esta é a empresa a a qual me refiro.'],
   'Ante el pronombre relativo "a qual" (femenino), cuando el verbo de la oración exige la preposición "a", el uso de la crasis es obligatorio.'),
  ('31014a67-5bf7-4027-b8e5-e1d3b09fa43c', 'en',
   'Choose the option in which the crase (à) is mandatory in Portuguese, before a place name that takes the article "a":',
   array['Viajarei à Bahia nas próximas férias.', 'Viajarei a Bahia nas próximas férias.', 'Viajarei em à Bahia nas próximas férias.', 'Viajarei para à Bahia nas próximas férias.'],
   'Since the place name "Bahia" takes the feminine article "a" ("gosto da Bahia"), the crase is mandatory before the preposition "a" required by the verb "viajar".'),
  ('31014a67-5bf7-4027-b8e5-e1d3b09fa43c', 'es',
   'Señala la alternativa en la que el uso de la crasis (à) es obligatorio en portugués, ante un nombre de lugar que admite el artículo "a":',
   array['Viajarei à Bahia nas próximas férias.', 'Viajarei a Bahia nas próximas férias.', 'Viajarei em à Bahia nas próximas férias.', 'Viajarei para à Bahia nas próximas férias.'],
   'Como el topónimo "Bahia" admite el artículo femenino "a" ("gosto da Bahia"), el uso de la crasis es obligatorio ante la preposición "a" que exige el verbo "viajar".'),
  ('1f212bd8-dac0-4b1c-bb61-1b841c040b4d', 'en',
   'Choose the option in which the crase (à) is mandatory in Portuguese, meaning "in the style of" ("à moda de"):',
   array['Ela se vestia à francesa.', 'Ela se vestia a francesa.', 'Ela se vestia à a francesa.', 'Ela se vestia na à francesa.'],
   'In expressions meaning "à moda de" (à francesa, à moda antiga), the crase is mandatory, even when the word "moda" is implied.'),
  ('1f212bd8-dac0-4b1c-bb61-1b841c040b4d', 'es',
   'Señala la alternativa en la que la crasis (à) es obligatoria en portugués, con el sentido de "al estilo de" ("à moda de"):',
   array['Ela se vestia à francesa.', 'Ela se vestia a francesa.', 'Ela se vestia à a francesa.', 'Ela se vestia na à francesa.'],
   'En expresiones que indican "à moda de" (à francesa, à moda antiga), el uso de la crasis es obligatorio, aunque la palabra "moda" esté implícita.'),
  ('1b99daa5-7b80-4215-ae0c-0947e10102a4', 'en',
   'Choose the option in which the crase (à) must NOT be used in Portuguese, because it comes before a verb:',
   array['Começou a chorar sem motivo aparente.', 'Começou à chorar sem motivo aparente.', 'Começou à a chorar sem motivo aparente.', 'Começou a à chorar sem motivo aparente.'],
   'The crase is not used before verbs, since verbs do not take a definite article: "começou a chorar".'),
  ('1b99daa5-7b80-4215-ae0c-0947e10102a4', 'es',
   'Señala la alternativa en la que la crasis (à) NO debe usarse en portugués, por ir antes de un verbo:',
   array['Começou a chorar sem motivo aparente.', 'Começou à chorar sem motivo aparente.', 'Começou à a chorar sem motivo aparente.', 'Começou a à chorar sem motivo aparente.'],
   'No se usa crasis ante verbos, pues estos no admiten artículo definido: "começou a chorar".'),
  ('64c0cb1e-3638-47b0-83bf-1c04ac6b5108', 'en',
   'Choose the option in which the crase (à) must NOT be used in Portuguese, because it comes before a masculine noun:',
   array['Fiz o trabalho a lápis.', 'Fiz o trabalho à lápis.', 'Fiz o trabalho à um lápis.', 'Fiz o trabalho à o lápis.'],
   'There is no crase before masculine nouns, since they are not preceded by the feminine article "a": "a lápis".'),
  ('64c0cb1e-3638-47b0-83bf-1c04ac6b5108', 'es',
   'Señala la alternativa en la que la crasis (à) NO debe usarse en portugués, por ir antes de un sustantivo masculino:',
   array['Fiz o trabalho a lápis.', 'Fiz o trabalho à lápis.', 'Fiz o trabalho à um lápis.', 'Fiz o trabalho à o lápis.'],
   'No hay crasis ante sustantivos masculinos, pues no van precedidos del artículo femenino "a": "a lápis".'),
  ('f326da7d-d01e-4ead-8a67-54107bd74512', 'en',
   'Choose the option in which the crase (à) must NOT be used in Portuguese, before a personal pronoun:',
   array['Entreguei o presente a ela.', 'Entreguei o presente à ela.', 'Entreguei o presente à-ela.', 'Entreguei o presente à a ela.'],
   'The crase is not used before subject personal pronouns such as "ela", which do not take a definite article.'),
  ('f326da7d-d01e-4ead-8a67-54107bd74512', 'es',
   'Señala la alternativa en la que la crasis (à) NO debe usarse en portugués, ante un pronombre personal:',
   array['Entreguei o presente a ela.', 'Entreguei o presente à ela.', 'Entreguei o presente à-ela.', 'Entreguei o presente à a ela.'],
   'No se usa crasis ante pronombres personales sujeto, como "ela", que no admiten artículo definido.'),
  ('e9f889f1-cf5a-4a0d-9cbe-8be5feb0b040', 'en',
   'Choose the option in which the crase (à) must NOT be used in Portuguese, before an unspecified plural word:',
   array['Referia-se a pessoas desconhecidas.', 'Referia-se à pessoas desconhecidas.', 'Referia-se às pessoa desconhecidas.', 'Referia-se à as pessoas desconhecidas.'],
   'With no definite article specifying the plural noun "pessoas" (indefinite meaning), there is no crase: "a pessoas desconhecidas".'),
  ('e9f889f1-cf5a-4a0d-9cbe-8be5feb0b040', 'es',
   'Señala la alternativa en la que la crasis (à) NO debe usarse en portugués, ante una palabra en plural sin determinación:',
   array['Referia-se a pessoas desconhecidas.', 'Referia-se à pessoas desconhecidas.', 'Referia-se às pessoa desconhecidas.', 'Referia-se à as pessoas desconhecidas.'],
   'Sin un artículo definido que determine el sustantivo plural "pessoas" (sentido indeterminado), no hay crasis: "a pessoas desconhecidas".'),
  ('01ba7740-19dd-4b77-8935-d4fbabf26f41', 'en',
   'Choose the option in which the crase (à) must NOT be used in Portuguese, before a person''s name without an article:',
   array['Entreguei a carta a Maria.', 'Entreguei a carta à Maria.', 'Entreguei a carta à-Maria.', 'Entreguei a carta à a Maria.'],
   'People''s proper names are generally not preceded by a definite article, which rules out the crase: "a Maria".'),
  ('01ba7740-19dd-4b77-8935-d4fbabf26f41', 'es',
   'Señala la alternativa en la que la crasis (à) NO debe usarse en portugués, ante un nombre propio de persona sin artículo:',
