   array['Pronombre', 'Artículo', 'Numeral', 'Interjección'],
   'Los pronombres sustituyen o acompañan a los sustantivos e indican persona, posesión u otras funciones.'),
  ('6ee75a00-0b69-47dd-85d9-4b3c1c0c6746', 'en',
